import json, numpy as np
base = {r['id']: r for r in json.load(open('/tmp/baseline.json'))}
ed1  = {r['id']: r for r in json.load(open('/tmp/edit1.json'))}
fin_b = [i for i,r in base.items() if not r['cut']]
fin_e = [i for i,r in ed1.items() if not r['cut']]
print("finished baseline:", len(fin_b), " edit1:", len(fin_e))
print("same finished set?", set(fin_b)==set(fin_e), "  new:", set(fin_e)-set(fin_b), " lost:", set(fin_b)-set(fin_e))
flips=[]
for i in base:
    if base[i]['correct']!=ed1[i]['correct']:
        flips.append((i, base[i]['correct'], ed1[i]['correct'], 'FIN' if not ed1[i]['cut'] else 'CUT'))
print("\nflips (id, base_ok, ed1_ok, status):")
for f in flips: print("  ", f)
# for the newly-correct: what did they do?
for i,b,e in [(f[0],f[1],f[2]) for f in flips if f[2] and not f[1]]:
    print("\nNEWLY CORRECT", i, "cut?", ed1[i]['cut'], "tok", ed1[i]['tokens'], "gold", ed1[i]['gold'])
    print("   tail:", ed1[i]['text'][-160:].replace('\n',' | '))
